const holder=document.createElement('div');holder.innerHTML=markup;document.body.append(holder);const pad=document.createElement('div');pad.id='possession-pad';pad.hidden=true;pad.innerHTML='<span id="possession-name"></span><div><button data-direction="ArrowUp" aria-label="Đi lên">↑</button></div><div><button data-direction="ArrowLeft" aria-label="Đi trái">←</button><button id="release-body">Rời</button><button data-direction="ArrowRight" aria-label="Đi phải">→</button></div><div><button data-direction="ArrowDown" aria-label="Đi xuống">↓</button></div>';$('viewport').append(pad);
