for(const [id,dialog,render] of [['god-open','god-dialog',()=>{syncLawControls();renderPrayers();renderDivineHud();}],['kingdom-open','kingdom-dialog',renderKingdoms],['laws-open','laws-dialog',syncLawControls],['chronicle-open','chronicle-dialog',renderChronicles]])$(id).onclick=()=>{render();$(dialog).showModal();};holder.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());for(const [name,label] of Object.entries({births:'Sinh sản',aging:'Già đi',war:'Chiến tranh',predators:'Sói săn mồi',disasters:'Thiên tai và lửa',disease:'Dịch bệnh lây lan',autoWar:'Vương quốc tự tuyên chiến'})){const row=document.createElement('label');row.className='law-row';const input=document.createElement('input');input.type='checkbox';input.dataset.law=name;input.checked=laws[name];input.onchange=()=>setLaw(name,input.checked);row.append(input,document.createTextNode(label));$('laws-list').append(row);}
$('infinite-power').onchange=e=>{divine.infinite=e.target.checked;renderDivineHud();};$('rename-god').onclick=()=>{const name=$('god-name').value.trim();if(!name){toast('Nhập tên vị thần.');return;}divine.name=name;remember('Thế giới biết đến tên '+name+'.');renderDivineHud();};for(const [id,state] of [['declare-war','war'],['declare-peace','peace']])$(id).onclick=()=>{try{setDiplomacy($('kingdom-a').value,$('kingdom-b').value,state);}catch(e){toast(e.message);}};$('chronicle-filter').onchange=renderChronicles;$('release-body').onclick=releasePossession;for(const b of pad.querySelectorAll('[data-direction]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.direction);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.direction);}
window.addEventListener('keydown',e=>{if(!possessed||document.querySelector('dialog[open]')||e.target.matches('input,select'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();keys.add(e.key);}});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());const li=document.createElement('li');li.textContent='Thần lực: ban phước, lời nguyền, mùa bội thu, đền thờ và sứ giả. Nút Thần mở tín ngưỡng và lời cầu nguyện; Vương quốc điều khiển chiến tranh; Luật thay đổi mô phỏng. Khám phá cư dân để xem đặc tính, thế hệ và nhập vai.';$('help-dialog').querySelector('ul').append(li);
