if(document.modelContext?.registerTool){const extraTools=[{name:'select_divine_tool',description:'Select a god power or fantasy species in the visible game toolbar.',inputSchema:{type:'object',properties:{tool:{type:'string',enum:[...Object.keys(miracleCosts),'elf','dwarf','orc']}},required:['tool'],additionalProperties:false},execute:input=>{if(!input||![...Object.keys(miracleCosts),'elf','dwarf','orc'].includes(input.tool))throw Error('Unknown divine tool');tab=Object.keys(groups).find(k=>groups[k].some(a=>a[0]===input.tool));document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderTools();choose(input.tool);return window.mamWorld.getState();}},{name:'set_world_law',description:'Change one simulation law, using the same state as the World laws dialog.',inputSchema:{type:'object',properties:{law:{type:'string',enum:Object.keys(lawDefaults)},enabled:{type:'boolean'}},required:['law','enabled'],additionalProperties:false},execute:input=>{setLaw(input?.law,input?.enabled);syncLawControls();return window.mamWorld.getState();}}];for(const t of extraTools)try{Promise.resolve(document.modelContext.registerTool({...t,annotations:{readOnlyHint:false}})).catch(()=>{});}catch{}}


